#include "layout_profiles.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
#define FILE_NAME "build/layout-profiles-test.ini"
static void seed(rtp_preferences *p){rtp_preferences_init(p);assert(rtp_preferences_register(p,"advanced-options","",RTP_ENTRY_CATEGORY,1,20)==0);assert(rtp_preferences_register(p,"system-tools","",RTP_ENTRY_CATEGORY,1,30)==0);assert(rtp_preferences_register(p,"vita-shell","system-tools",RTP_ENTRY_TOOL,1,10)==0);assert(rtp_preferences_register(p,"ftp-auto-start","advanced-options",RTP_ENTRY_SETTING,1,20)==0);}
int main(void){rtp_preferences p,q;rtp_profile_store s,t;const rtp_menu_entry *e;FILE *f;seed(&p);rtp_profiles_init(&s);assert(rtp_profiles_create(&s,"default","Default",&p)==0);assert(rtp_profiles_create(&s,"minimal","Minimal",&p)==0);assert(rtp_preferences_set_visible(&p,"vita-shell",0)==0);assert(rtp_preferences_set_order(&p,"vita-shell",77)==0);assert(rtp_profiles_update(&s,"minimal",&p)==0);seed(&q);assert(rtp_profiles_apply(&s,"minimal",&q)==0);e=rtp_preferences_find(&q,"vita-shell");assert(e&&!e->visible&&e->order==77);assert(!strcmp(s.active_id,"minimal"));assert(rtp_profiles_rename(&s,"minimal","Compact")==0);assert(rtp_profiles_rename(&s,"default","Nope")==RTP_PROFILE_PROTECTED);assert(rtp_profiles_save(&s,FILE_NAME)==0);rtp_profiles_init(&t);assert(rtp_profiles_load(&t,FILE_NAME)==0);assert(rtp_profiles_find(&t,"minimal")!=NULL);assert(!strcmp(rtp_profiles_find(&t,"minimal")->name,"Compact"));assert(rtp_profiles_delete(&t,"default")==RTP_PROFILE_PROTECTED);assert(rtp_profiles_delete(&t,"minimal")==0);f=fopen(FILE_NAME,"wb");assert(f);fputs("BROKEN\n",f);fclose(f);{rtp_profile_store old=t;assert(rtp_profiles_load(&t,FILE_NAME)==RTP_PROFILE_INVALID_DATA);assert(!memcmp(&t,&old,sizeof(t)));}remove(FILE_NAME);puts("Layout profile tests passed.");return 0;}
